import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.B7PviQjB.js";const u=JSON.parse(`{"title":"Use the desktop app","description":"Install the Wafflebase desktop app on a Mac or Windows PC, sign in, connect it to your team's server, and keep it up to date.","frontmatter":{"title":"Use the desktop app","description":"Install the Wafflebase desktop app on a Mac or Windows PC, sign in, connect it to your team's server, and keep it up to date.","type":"how-to"},"headers":[],"relativePath":"start/desktop.md","filePath":"start/desktop.md"}`),n={name:"start/desktop.md"};function r(i,e,l,h,p,d){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="use-the-desktop-app" tabindex="-1">Use the desktop app <a class="header-anchor" href="#use-the-desktop-app" aria-label="Permalink to &quot;Use the desktop app&quot;">​</a></h1><p>Install the Wafflebase desktop app on a Mac or Windows PC, sign in, connect it to your team&#39;s server, and keep it up to date.</p><p>The app opens the same Wafflebase you use in a browser, in its own window. Your account, documents, and share links are the same in both.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Available for macOS (Apple silicon and Intel) and Windows (64-bit). A Linux version is not available yet.</li><li>Sign in with GitHub. Google sign-in isn&#39;t available in the desktop app yet.</li><li>Documents need a connection to the server. You can&#39;t edit offline.</li></ul></div><div class="tip custom-block"><p class="custom-block-title">Download says Not Found?</p><p>The download links point at the latest Wafflebase release. If one answers <strong>Not Found</strong>, that release doesn&#39;t include the app yet, or was published in the last half hour and is still being built. Try again later, or see the <a href="https://github.com/wafflebase/wafflebase/releases" target="_blank" rel="noreferrer">releases page</a>.</p></div><h2 id="install-on-a-mac" tabindex="-1">Install on a Mac <a class="header-anchor" href="#install-on-a-mac" aria-label="Permalink to &quot;Install on a Mac&quot;">​</a></h2><ol><li>Download <a href="https://github.com/wafflebase/wafflebase/releases/latest/download/Wafflebase_universal.dmg" target="_blank" rel="noreferrer">Wafflebase_universal.dmg</a>.</li><li>Open the downloaded file.</li><li>Drag <strong>Wafflebase</strong> into the <strong>Applications</strong> folder.</li><li>Open <strong>Wafflebase</strong> from <strong>Applications</strong> or Launchpad.</li></ol><p>The Mac app is signed and notarized by Apple, so it opens without a security warning.</p><h2 id="install-on-windows" tabindex="-1">Install on Windows <a class="header-anchor" href="#install-on-windows" aria-label="Permalink to &quot;Install on Windows&quot;">​</a></h2><ol><li>Download <a href="https://github.com/wafflebase/wafflebase/releases/latest/download/Wafflebase_x64-setup.exe" target="_blank" rel="noreferrer">Wafflebase_x64-setup.exe</a>.</li><li>Open the downloaded file.</li><li>If <strong>Windows protected your PC</strong> appears, click <strong>More info</strong>, then click <strong>Run anyway</strong>.</li><li>Follow the installer, then open <strong>Wafflebase</strong> from the Start menu.</li></ol><p>The Windows installer is not code-signed yet, so Windows SmartScreen warns you the first time you run it. Only run an installer you downloaded from the link above.</p><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><p>The first time you open the app, it shows the sign-in page of the official server, <a href="https://wafflebase.io" target="_blank" rel="noreferrer">wafflebase.io</a>. To use your team&#39;s own server instead, <a href="#connect-to-your-team-s-server">connect to it</a> first.</p><ol><li>Click <strong>Continue with GitHub</strong>.</li><li>Your web browser opens on <strong>Continue signing in to the Wafflebase desktop app?</strong> Click <strong>Continue</strong>.</li><li>Approve the request on GitHub&#39;s page, if it asks.</li><li>When the browser tab says <strong>Return to Wafflebase</strong>, switch back to the app.</li></ol><p>The app comes to the front and opens your documents. The browser tab is no longer needed, and you stay signed in the next time you open the app.</p><p>Signing in happens in your browser so you can use its saved passwords and passkeys. If the app shows a message instead, see <a href="/docs/start/troubleshooting.html#this-server-is-too-old-for-desktop-sign-in">Troubleshooting</a>.</p><h2 id="connect-to-your-team-s-server" tabindex="-1">Connect to your team&#39;s server <a class="header-anchor" href="#connect-to-your-team-s-server" aria-label="Permalink to &quot;Connect to your team&#39;s server&quot;">​</a></h2><p>If your team runs its own Wafflebase, point the app at it. The app connects to one server at a time.</p><ol><li>Open the <strong>Change server…</strong> menu item. On a Mac it&#39;s in the <strong>Wafflebase</strong> menu. On Windows it&#39;s in the <strong>File</strong> menu.</li><li>Under <strong>Server address</strong>, enter the address you open Wafflebase at in a web browser, for example <code>https://wafflebase.example.com</code>.</li><li>Click <strong>Connect</strong>.</li></ol><p>The app opens that server&#39;s sign-in page and remembers it the next time you start the app. The address must start with <code>https://</code>. Plain <code>http://</code> works only for <code>localhost</code>.</p><p>To go back to the official server, open <strong>Change server…</strong> again and click <strong>Use wafflebase.io</strong>.</p><h2 id="work-in-the-app" tabindex="-1">Work in the app <a class="header-anchor" href="#work-in-the-app" aria-label="Permalink to &quot;Work in the app&quot;">​</a></h2><ul><li><strong>Links:</strong> links to other websites, and to this documentation, open in your web browser. Links inside Wafflebase stay in the app.</li><li><strong>Windows:</strong> a link that opens in a new tab in a browser opens a new app window instead. Each window is titled after the document in it.</li><li><strong>Back, Forward, and Reload:</strong> the window has no address bar or toolbar. Use the <strong>View</strong> menu to go back, go forward, or reload the page.</li><li><strong>Downloads:</strong> exported and downloaded files go straight to your <strong>Downloads</strong> folder. A file with the same name gets a number added, such as <code>budget (1).xlsx</code>, instead of replacing the old one.</li></ul><p>Editor keyboard shortcuts work the same as in a browser. See the shortcuts for <a href="/docs/sheets/keyboard-shortcuts.html">Sheets</a>, <a href="/docs/docs-editor/keyboard-shortcuts.html">Docs</a>, <a href="/docs/slides/keyboard-shortcuts.html">Slides</a>, <a href="/docs/notes/keyboard-shortcuts.html">Notes</a>, and <a href="/docs/board/keyboard-shortcuts.html">Board</a>.</p><h2 id="keep-the-app-up-to-date" tabindex="-1">Keep the app up to date <a class="header-anchor" href="#keep-the-app-up-to-date" aria-label="Permalink to &quot;Keep the app up to date&quot;">​</a></h2><p>The app checks for a new version when it starts and once a day. It downloads the update in the background and installs it when you quit, so the next launch runs the new version.</p><p>On a Mac where your account can&#39;t change the app (for example, an admin installed it in <strong>Applications</strong> for everyone), the app can&#39;t install updates when you quit. Use <strong>Check for Updates…</strong> and click <strong>Restart Now</strong> instead, and enter an administrator&#39;s password when macOS asks.</p><p>To check now:</p><ol><li>Open the <strong>Check for Updates…</strong> menu item, next to <strong>Change server…</strong>.</li><li>If an update is available, click <strong>Restart Now</strong> to install it, or <strong>Later</strong> to install it when you quit.</li></ol><p>If you already have the latest version, the app says <strong>You&#39;re up to date</strong>.</p><p>The editors and their features come from the server, not from the app. When your server is upgraded, you get the new features without updating the app.</p><h2 id="use-the-app-offline" tabindex="-1">Use the app offline <a class="header-anchor" href="#use-the-app-offline" aria-label="Permalink to &quot;Use the app offline&quot;">​</a></h2><p>When the app can&#39;t reach the server, it shows <strong>Can&#39;t reach</strong> and the server&#39;s address, with the likely cause. It tries again on its own, and opens the server as soon as it answers. Click <strong>Try again</strong> to check now, or <strong>Change server…</strong> to pick another server. If it keeps failing, see <a href="/docs/start/troubleshooting.html#can-t-reach-appears-in-the-desktop-app"><strong>Can&#39;t reach</strong> appears in the desktop app</a>.</p><p>After you&#39;ve used the app online once, it can start with no connection. It then shows <strong>You&#39;re offline</strong>. Your documents are stored on the server, so they open again once the connection is back.</p><p>If the connection drops while a document is open, the app works like a browser tab. See <a href="/docs/collaborate/edit-together.html">Edit together</a> for what the <strong>Saving…</strong>, <strong>Reconnecting…</strong>, and <strong>Not saved</strong> indicators mean.</p><h2 id="set-up-your-server" tabindex="-1">Set up your server <a class="header-anchor" href="#set-up-your-server" aria-label="Permalink to &quot;Set up your server&quot;">​</a></h2><p>For team admins who run their own Wafflebase:</p><ul><li>Run a recent version of Wafflebase. An older server can&#39;t sign in from the desktop app, and the app says so.</li><li>Serve sign-in over <code>https://</code>, the same rule as CLI sign-in. See <a href="/docs/developers/self-hosting/sign-in.html#allow-desktop-app-sign-in">Allow desktop app sign-in</a>.</li><li>Tell your team to enter the address the server redirects to after sign-in (<code>FRONTEND_URL</code>), not an alias. With an alias, sign-in ends in the browser instead of the app.</li></ul><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>No Linux version yet.</li><li>Google sign-in isn&#39;t available in the app yet. Use GitHub, or use Google in a web browser.</li><li>No offline editing. Documents open only while the app can reach the server.</li><li>The app connects to one server at a time.</li><li>A Wafflebase link you click in another app, such as email or chat, opens in your browser, not in the desktop app.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/start/getting-started.html">Getting started</a>: build and share your first sheet</li><li><a href="/docs/start/phone.html">Use Wafflebase on a phone</a>: what works on a small screen</li><li><a href="/docs/start/troubleshooting.html">Troubleshooting</a>: fix sign-in and connection problems in the app</li><li><a href="/docs/developers/self-hosting/sign-in.html">Sign-in providers</a>: set up sign-in on your own server</li></ul>',42)])])}const f=t(n,[["render",r]]);export{u as __pageData,f as default};
